import numpy as np

X = np.array([[0, 1], [1, 0]], complex); Z = np.diag([1, -1]).astype(complex)
def op(o, i, n):
    m = np.array([[1]], complex)
    for k in range(n): m = np.kron(m, o if k == i else np.eye(2))
    return m
def hamiltonian(n, h, W, rng):
    H = sum(rng.uniform(-0.5, 0.5) * op(X, i, n) @ op(X, j, n) for i in range(n) for j in range(i + 1, n))
    return np.real(H + sum((h + rng.uniform(-W / 2, W / 2)) * op(Z, i, n) for i in range(n)))

def ratios(E, middle=True):
    if middle: E = E[len(E) // 4: 3 * len(E) // 4]          # middle half of the spectrum
    g = np.diff(E); return np.minimum(g[1:], g[:-1]) / np.maximum(g[1:], g[:-1])

# the arithmetic of the ratio on five made-up levels
lv = np.array([0, 1, 3, 4.5, 5.0]); print("levels", lv, "gaps", np.diff(lv), "ratios", np.round(ratios(lv, False), 3))

for n in (8, 10):
    par = np.array([(-1) ** bin(a).count("1") for a in range(2 ** n)])
    full, block = [], []
    for k in range(4 if n == 8 else 1):
        H = hamiltonian(n, 1.0, 1.0, np.random.default_rng(k))      # h = 1, W = 1
        full += list(ratios(np.linalg.eigvalsh(H)))
        block += list(ratios(np.linalg.eigvalsh(H[np.ix_(par == 1, par == 1)])))
    print(f"n={n}: <r> over the whole spectrum {np.mean(full):.3f}; inside the even-parity block {np.mean(block):.3f}")
